        low[v] = low[v] < disc[u] ? low[v] : disc[u];
      }
    }
    if (low[v] == disc[v]) {
      while (true) {
        int w = stack.removeLast();
        onStack[w] = true;
        if (w == v) break;
      }
    }
  }

