  List<int> low = List.filled(n, -1);
  List<int> parent = List.filled(n, -1);
  List<int> topoSort = [];

  for (int i = 0; i < n; i++) {
    if (!visited[i]) {
      dfs(i, visited, disc, low, parent);
    }
  }

  Queue<int> queue = Queue<int>();
  for (int i = 0; i < n; i++) {
