Map<String, List<String>> wordBreakAll(String s, List<String> wordDict) {
  Set<String> dictionary = wordDict.toSet();
  Map<String, List<String>> segmentations = {};

  void search(int start, List<String> current, List<String> rest) {
    if (start == s.length) {
      if (current.isEmpty) return;
      segmentations[current.join(' ')] = rest;
      return;
    }

    for (int j = start; j < s.length; j++) {
      if (dictionary.contains(s.substring(start, j + 1)) && !rest.contains(s.substring(j + 1, start))) {
        current.add(s.substring(start, j + 1));
        search(j + 1, current, rest..add(s.substring(j + 1, start))..remove(s.substring(start, j + 1)));
        current.removeLast();
      }
    }
  }

  for (int i = 0; i <= s.length; i++) {
    List<String> current = [];
    search(i, current, <String>[]);
  }
  return segmentations;
}

List<String> minWordBreak(String s, List<String> wordDict) {
  Set<String> dictionary = wordDict.toSet();
  int n = s.length;
  List<int> dp = List.filled(n + 1, 1 << 30);
  dp[0] = 0;

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] != 1 << 30 && dictionary.contains(s.substring(j, i))) {
        if (dp[i] > dp[j] + 1) dp[i] = dp[j] + 1;
      }
    }
  }

  List<String> result = [];
  int count = dp[n];
  int index = n;

  while (count > 0) {
    if (dp[count] != 1 << 30) {
      result.add(s.substring(dp[count], index));
      count -= 1;
    } else {
      count -= 1;
    }
  }

  return result;
}

