  List<int> counts = List.filled(handSize, 0);
  for (int i = left; i <= right; i++) {
    int idx = i % n;
    if (idx >= handSize) break;
    counts[idx]++;
  }
  for (int size = handSize; size <= n; size++) {
    int l = left;
