    int optimalStart = l;
    int optimalEnd = spread + l - 1;
    for (int start = 0; start <= n - size; start++) {
      int end = start + size - 1;
      int mergeSum = 0;
      for (int i = start; i <= optimalEnd; i++) {
        mergeSum += deck[i];
      }
      for (int j = optimalStart; j <= end; j++) {
        mergeSum += deck[j];
      }
      if (mergeSum > 0) {
        counts[start] += mergeSum;
      }
    }
  }
