List<String> generateCombinations(List<String> items, int k) {
  if (k == 0) return [[]];

  List<String> result = [];
  List<String> remaining = List.generate(items.length, (i) => items[i]);

  while (k > 0) {
    int j = k;
    while (j > 0 && remaining[j - 1] == remaining[0]) j--;
    String first = remaining[j - 1];
    remaining.removeAt(j - 1);

    List<String> sub = generateCombinations(remaining, k - 1);

    for (String s in sub) {
      result.add([first, ...s]);
    }
  }

  return result;
}

