      }
      int count = 0;
      for (int i = 0; i < dna.length; i++) {
        if (base == dna[i]) {
          count++;
        }
      }
      if (count == symbol.length) {
        matches.add(symbol);
      }
    }
    groups.add(matches);
  }

  for (String symbol in groups[0]) {
    for (List<String> matches in groups.sublist(1)) {
      if (matches.contains(symbol)) {
        matches.remove(symbol);
      }
    }
  }

  List<String> result = [];
