    double n = norm;
    if (n != 0) {
      x = x / n;
      y = y / n;
      z = z / n;
      w = w / n;
    }
  }

  void rotate(Quaternion axis, double angle) {
    double cos = 0.5 * axis.norm * angle;
    double sin = (1 - cos).abs();
    double x = axis.x * sin;
