import 'dart:async';
import 'dart:convert';
class Quaternion {
  double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  const ZERO = Quaternion(0, 0, 0, 0);

  const IDENTITY = Quaternion(1, 0, 0, 0);

  const NEGATIVE_ONE = Quaternion(-1, 0, 0, 0);

  const UNIT_Z = Quaternion(0, 0, 1, 0);

  const UNIT_Y = Quaternion(0, 1, 0, 0);

  const UNIT_X = Quaternion(0, 0, 0, 1);

  const UNIT_W = Quaternion(0, 0, 0, 1);

  const UNIT_T = Quaternion(0, 0, 0, -1);

  double norm() {
    double sum = x * x + y * y + z * z + w * w;
    return sum > 0 ? sum : 0.0;
  }

  Quaternion normalize() {
    double normVal = norm();
    if (normVal == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / normVal, y / normVal, z / normVal, w / normVal);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    double normVal = norm();
    if (normVal == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(x / normVal, y / normVal, z / normVal, -w / normVal);
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(Quaternion other) {
    double t = x * other.w - y * other.z - z * other.y - w * other.x;
    double u = x * other.z + y * other.w - z * other.x - w * other.y;
    double v = x * other.y + y * other.z + z * other.w - w * other.x;
    return Quaternion(t, u, v, w * other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  void rotate(Quaternion axis, double angle) {
    Quaternion e = Quaternion(axis.x, axis.y, axis.z, 0);
    Quaternion axisToUnit = Quaternion(axis.x, axis.y, axis.z, 1);
    double halfAngle = angle / 2;
    Quaternion side1 = Quaternion.UNIT_X.cos(halfAngle) + axisToUnit.sin(halfAngle);
    Quaternion side2 = Quaternion.UNIT_Y.cos(halfAngle) + e.sin(halfAngle) * axisToUnit;
    Quaternion side3 = Quaternion.UNIT_Z.cos(halfAngle) + e.sin(halfAngle) * axisToUnit.conjugate();
    Quaternion side4 = Quaternion.UNIT_W.cos(halfAngle) + axisToUnit.sin(halfAngle);
    this.x = side1 * x + side2 * y + side3 * z + side4 * w;
    this.y = side2 * x + side3 * y + side4 * z + side1 * w;
    this.z = side3 * x + side4 * y + side1 * z + side2 * w;
    this.w = side4 * x + side1 * y + side2 * z + side3 * w;
  }

  void print() {
    print('q1 = ${x.toStringAsFixed(2)} + ${y.toStringAsFixed(2)}i + ${z.toStringAsFixed(2)}j + ${w.toStringAsFixed(2)}k');
  }
}

