  final int order;

  const Quaternion._internal(this.x, this.y, this.z, this.w, this.order);

  factory Quaternion(List<double> components) {
    final int order = components.length;
    if (order == 0) return const Quaternion._internal(0.0, 0.0, 0.0, 0.0, 0);
    final double x = components[0], y = components[1], z = components[2], w = components[3];
    return const Quaternion._internal(x, y, z, w, order);
  }

  const Quaternion(this.x, this.y, this.z, this.w) : this._internal(x, y, z, w, 4);

  const Quaternion.unit = const Quaternion(1.0, 0.0, 0.0, 1.0);
  const Quaternion.zero = const Quaternion(0.0, 0.0, 0.0, 0.0);
  const Quaternion.one = const Quaternion(1.0, 1.0, 1.0, 1.0);

  const Quaternion.rotation(double angle, Vector3 axis) {
    final double cos = angle * 0.5;
    final double sin = angle * 0.5;
    final Vector3 normalized = axis.normalize();
    final double x = normalized.x, y = normalized.y, z = normalized.z;
    return const Quaternion(
      (x * x * cos + sin) * 4.0,
      (y * x * cos + z * sin) * 4.0,
      (z * x * cos - y * sin) * 4.0,
      (y * y * cos + z * sin) * 4.0,
    );
  }

  const Quaternion.inverse(this) : this(-x, -y, -z, -w);

  const Quaternion operator +(this) : this(
        x + w * x,
        y + w * y,
        z + w * z,
        w + x * x + y * y + z * z,
      );

  const Quaternion operator -(this) : this(x - w * x, y - w * y, z - w * z, w - x * x - y * y - z * z);

  const Quaternion operator * (this) : this(
        x * w + w * x,
        y * w + w * y,
        z * w + w * z,
        w * w - x * x - y * y - z * z,
      );

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  Vector3 get vector => Vector3(x, y, z);

  Quaternion conjugate() => const Quaternion(x, y, z, w);

  @override
  String toString() =>
      'q$order: (${x.toStringAsFixed(2)}, ${y.toStringAsFixed(2)}, ${z.toStringAsFixed(2)}, ${w.toStringAsFixed(2)})';

  @override
  bool operator ==(Object other) =>
      other is Quaternion &&
      x == other.x &&
      y == other.y &&
      z == other.z &&
      w == other.w;

  @override
  int get hashCode =>
      x.hashCode ^
