    out[0] = components[0];
    out[1] = components[1];
    out[2] = -components[2];
    out[3] = components[3];
    return norm;
  }

  double normSquared => components[0] * components[0] + components[1] * components[1] + components[2] * components[2] + components[3] * components[3];

  double norm => normSquared > 0.0 ? normSquared : 0.0;

  Quaternion inverse() {
    if (norm == 0.0) throw ArgumentError('Cannot invert zero quaternion');
    final double invNorm = 1.0 / norm;
    final List<double> out = [components[0] * invNorm, components[1] * invNorm, components[2] * invNorm, components[3] * invNorm];
    return Quaternion(out);
  }

  Quaternion normalize() {
    if (norm == 0.0) throw ArgumentError('Cannot normalize zero quaternion');
    final double invNorm = 1.0 / norm;
    final List<double> out = [components[0] * invNorm, components[1] * invNorm, components[2] * invNorm, components[3] * invNorm];
    return Quaternion(out);
  }

  Quaternion operator +(List<double> out) {
    out[0] = components[0] + out[0];
    out[1] = components[1] + out[1];
    out[2] = components[2] + out[2];
    out[3] = components[3] + out[3];
    return Quaternion(out);
  }

  Quaternion operator -(List<double> out) {
    out[0] = components[0] - out[0];
    out[1] = components[1] - out[1];
    out[2] = components[2] - out[2];
    out[3] = components[3] - out[3];
    return Quaternion(out);
  }

  Quaternion operator *(List<double> out) {
    double a0 = components[0], a1 = components[1], a2 = components[2], a3 = components[3];
    double b0 = out[0], b1 = out[1], b2 = out[2], b3 = out[3];
    out[0] = a0 * b0 - a1 * b1 - a2 * b2 - a3 * b3;
    out[1] = a0 * b1 + a1 * b0 + a2 * b3 - a3 * b2;
    out[2] = a0 * b2 - a1 * b3 + a2 * b0 - a3 * b1;
    out[3] = a0 * b3 + a1 * b2 + a2 * b1 - a3 * b0;
    return Quaternion(out);
  }

  Quaternion operator *() {
    final List<double> out = [components[0] * components[0], components[1] * components[1], components[2] * components[2], components[3] * components[3]];
