  const Quaternion.unitX() : this(1.0, 0.0, 0.0, 0.0);

  const Quaternion.unitY() : this(0.0, 1.0, 0.0, 0.0);

  const Quaternion.unitZ() : this(0.0, 0.0, 1.0, 0.0);

  const Quaternion.unitW() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.one() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.minusOne() : this(-1.0, -1.0, -1.0, -1.0);

  const Quaternion.unitNorm() : this(0.5, 0.5, 0.5, 0.5);

  const Quaternion.random() {
    final rand = Random(0);
    return Quaternion(
      rand.nextBool() ? rand.nextDouble() : -rand.nextDouble(),
      rand.nextBool() ? rand.nextDouble() : -rand.nextDouble(),
      rand.nextBool() ? rand.nextDouble() : -rand.nextDouble(),
      rand.nextBool() ? rand.nextDouble() : -rand.nextDouble(),
    );
  }

  const Quaternion.fromAxisAngle(Axis axis, double angle) {
    switch (axis) {
      case Axis.x:
        return Quaternion.unitX() * angle;
      case Axis.y:
        return Quaternion.unitY() * angle;
      case Axis.z:
        return Quaternion.unitZ() * angle;
      default:
        throw ArgumentError('Invalid axis');
    }
  }

  Quaternion operator +(const Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(const Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(const Quaternion other) {
    final q2 = other;
    return Quaternion(
      (x * q2.w) - (y * q2.z) - (z * q2.y) + (w * q2.x),
      (x * q2.z) + (y * q2.w) - (z * q2.x) + (w * q2.y),
      (x * q2.y) - (y * q2.x) + (z * q2.w) - (w * q2.z),
      (x * q2.w) + (y * q2.x) + (z * q2.y) - (w * q2.z),
    );
  }

  Quaternion operator -() {
    return Quaternion(-x, -y, -z, -w);
  }

  Quaternion operator ~() {
    return Quaternion(
      w,
      -x,
      -y,
      -z,
    );
  }

  Quaternion operator ^(int exponent) {
    if (exponent == 0) return Quaternion.identity();
    final q = this;
    final base = Quaternion.unitNorm() * sqrt(q.w);
    if (exponent % 2 == 0) {
      return base * q * base;
    }
    return q * base * q * base;
  }

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  double norm2() {
    return x * x + y * y + z * z + w * w;
  }

  double angle() {
    final norm = norm();
    if (norm == 0) return 0.0;
    final cos = x * x + y * y + z * z + w * w;
    final sin = sqrt(1 - cos);
    return acos(cos / norm);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  void rotate(const Quaternion axis, double angle) {
    final q = Quaternion.fromAxisAngle(axis, angle);
    *this = this * q;
  }

  @override
  bool operator ==(Object other) {
    if (other is! Quaternion) return false;
    final q = other as Quaternion;
    return x == q.x && y == q.y && z == q.z && w == q.w;
  }

  @override
  int get hashCode {
    return x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;
  }

  @override
  String toString() {
    return '($x, $y, $z, $w)';
  }
}

