  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.unit =>
      const Quaternion(0.0, 0.0, 0.0, 1.0);

  const Quaternion.zero =>
      const Quaternion(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromAxisAngle(const Vector3 axis, double angle) {
    final cosHalf = 0.5 * angle.normalized().dot(axis.normalized());
    final sinHalf = 0.5 * angle.normalize().cross(axis.normalized()).abs();
    return Quaternion(axis.x * sinHalf, axis.y * sinHalf, axis.z * sinHalf, cosHalf);
  }

  const Quaternion.fromBasis(const Vector3 v1, const Vector3 v2, const Vector3 v3) {
    final m = v1.cross(v2).cross(v3);
    final n = v1.dot(v2) * 2.0 - v1.dot(v3) - v2.dot(v3);
    return const Quaternion(m.x, m.y, m.z, n);
  }

  const Quaternion.fromSkew(const Vector3 v1, const Vector3 v2) {
    final m = v1.cross(v2);
    final n = v1.dot(v2);
    return Quaternion(m.x, m.y, m.z, n);
  }

  Quaternion operator +(const Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(const Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(const Quaternion other) =>
      Quaternion(
          x * other.w - y * other.z - z * other.y + w * other.x,
          y * other.w - x * other.z - z * other.x + w * y,
          z * other.w - x * other.y - y * other.x + w * z,
          w * other.w);

  Quaternion conjugate() =>
      const Quaternion(x, y, z, -w);

  double norm() => (x * x + y * y + z * z + w * w).sqrt();

  double normalize() => norm() == 0.0 ? 0.0 : (1.0 / norm()) * this;

  void rotateAboutAxis(const Vector3 axis, double angle) {
    final q = Quaternion.fromAxisAngle(axis, angle);
    *this = *this * q;
  }

  void rotateAboutOrigin(const Vector3 axis, double angle) {
    final q = Quaternion.fromAxisAngle(axis, angle);
    *this = *this * q * conjugate();
  }

  void invert() => *this = conjugate() * (1.0 / norm());
}

