Map<String, int> fn0(List<String> symbols, List<int> counts) {
  int n = symbols.length;
  List<int> prefix = List.filled(n, 0);
  List<int> suffix = List.filled(n, 0);

  for (int i = 0; i < n; i++) {
    prefix[i] = i == 0 ? counts[i] : counts[i] + prefix[i - 1];
  }

  for (int i = n - 1; i >= 0; i--) {
    suffix[i] = i == n - 1 ? counts[i] : counts[i] + suffix[i + 1];
  }

  int maxPrefix = 0;
  int maxSuffix = 0;

  for (int i = 0; i < n; i++) {
    if (prefix[i] > maxPrefix) {
      maxPrefix = prefix[i];
    }

    if (suffix[i] > maxSuffix) {
      maxSuffix = suffix[i];
    }
  }

  int minPrefix = 0;
  int minSuffix = 0;

  for (int i = 0; i < n; i++) {
    if (prefix[i] + maxSuffix > minPrefix) {
      minPrefix = prefix[i] + maxSuffix;
    }

    if (suffix[i] + maxPrefix > minSuffix) {
      minSuffix = suffix[i] + maxPrefix;
    }
  }

  int left = 0;
  int right = n - 1;
  int bestLen = 0;
  int bestIdx = 0;

  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    int total = 0;
    int minPrefixIdx = mid;

    for (int i = mid; i < n; i++) {
      if (prefix[i] + maxSuffix > minPrefix) {
        minPrefix = prefix[i] + maxSuffix;
        minPrefixIdx = i;
      }
    }

    int len = minPrefixIdx - mid + 1;

    if (len > bestLen) {
      bestLen = len;
      bestIdx = mid;
    }

    if (len + minSuffix > total) {
      total = len + minSuffix;
    }

    if (total > bestPrefix) {
      bestPrefix = total;
    }

    if (bestPrefix < minPrefix) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  Map<String, int> result = {};

  for (int i = bestIdx; i < bestIdx + bestLen; i++) {
    result[symbols[i]] = counts[i];
  }

  return result;
}

