        dp[i][j] = best;
      }
    }
  }
  Map<String, int> result = {};
  for (int i = 0; i < n; i++) {
    for (int j = i; j < n; j++) {
      if (dp[i][j] == 0) continue;
      result["${rows[i]}-${rows[j]}"] = dp[i][j];
    }
  }
  return result;
}

