  final Map<String, Map<String, Map<String, int>>> permissionsForRole(String role) {
    if (!permissions.containsKey(role)) {
      return {};
    }
    final Map<String, Map<String, int>> result = {};
    permissions[role]!.forEach((resource, actions) {
      for (final action in actions.values) {
        result[resource] = (result[resource] ?? {})..[action] = (result[resource]![action] ?? 0) + 1;
      }
    });
    return result;
  }

  final Map<String, Map<String, List<String>>> roleHierarchy = {
    'admin': ['admin'],
    'moderator': ['moderator'],
    'viewer': ['viewer'],
  };

  String parseRolePath(String role) {
    final parts = role.split('|');
    if (parts.isEmpty) {
      return role;
    }
    String result = parts[0];
    for (int i = 1; i < parts.length; i++) {
      result += '->${parts[i]}';
    }
    return result;
