      'bob': 'editor',
      'charlie': 'moderator',
      'diana': 'admin',
    };

    for (final newRole in grantMap.keys) {
      if (user == newRole) {
        print('Elevating $user to $newRole...');
        roles[newRole] = roles[newRole]!.toList()
          ..add(parseRolePath(currentRole));
        print('New role for $user: ${parseRolePath(newRole)}');
        break;
      }
    }

    print('--- Audit Log ---\n');
    final List<Map<String, Object>> auditLog = [
      {'timestamp': '2024-01-01 10:00:00', 'status': 'SUCCESS', 'action': 'GRANT', 'role': parseRolePath(newRole)},
