      print('  ${entry['timestamp']}  ${entry['status']}  ${entry['action']}  ${entry['role']}');
    }

    print('\nAttempting to access admin resource...');
    final Map<String, List<String>> resourceAccess = {
      'document1': ['read', 'edit'],
      'document2': ['read', 'delete'],
      'sensitive_data': ['read', 'write'],
    };

    final Map<String, Map<String, String>> resourceAccessMap = {
      'document1': {
        'alice': 'viewer',
        'bob': 'editor',
        'charlie': 'moderator',
        'diana': 'admin',
      },
      'document2': {
        'alice': 'viewer',
        'bob': 'editor',
        'charlie': 'moderator',
        'diana': 'admin',
      },
      'sensitive_data': {
        'alice': 'viewer',
        'bob': 'editor',
        'charlie': 'moderator',
        'diana': 'admin',
      },
    };

    print('User/Resource Access Matrix:');
    for (final resource in resourceAccess.keys) {
      print('  $resource:');
      for (final user in users) {
        String role = resourceAccessMap[resource]![user]!;
        print('    $user → ${parseRolePath(role)}');
      }
    }

    print('\nRecent Access Attempts:');
    for (final user in users) {
      print('  ${user} attempts to ${resourceAccess[resource]!}');
    }

    print('\n=== System Summary ===\n');
    print('Total Users: ${users.length}\n');
    print('Total Resources: ${resourceAccess.length}\n');
    print('Total Roles: ${roles.length}\n');
    print('Total Permissions: ${permissionsForRole(roles.keys.first).length}\n');
    print('Role Hierarchy:');
    final Map<String, List<String>> roleTree = {};
    for (final role in roles.keys) {
      final List<String> parents = roleHierarchy[role] ?? [];
      while (parents.isNotEmpty) {
        final String top = parents.removeAt(0);
        roleTree[top] = (roleTree[top] ?? [])..add(role);
      }
    }

    final Map<String, List<String>> flattened = [];
    String current = '';
    for (final role in roles.keys) {
      if (current != role) {
        current = role;
        flattened.add(current);
      }
    }

    for (final role in flattened) {
      print('  $role:');
      final List<String> children = roleTree[role] ?? [];
      for (final child in children) {
        print('    $child');
      }
    }
  }
}

