    frequentK.sort((a, b) {
      int aLen = a.length;
      int bLen = b.length;
      if (aLen != bLen) return aLen.compareTo(bLen);
      return a.toList().sort().compareTo(b.toList().sort());
    });

    for (int j = 0; j < frequentK.length; j++) {
      if (!allItems.contains(frequentK[j])) {
        allItems.add(frequentK[j]);
      }
    }

    if (frequentK.length >= i) {
      frequentItemsets[frequentK] = (frequentItemsets[frequentK] ?? 0) + 1;
    }
