  for (var entry in frequentItemsets.entries) {
    if (entry.value >= minSupport * 2) {
      print(entry.key.toList().sort() + ' -> ' + entry.key.toList().sort().join(', ') + ' (support: ${entry.value / transactions.length}, confidence: ${entry.value * 2 / (transactions.length + 1)})');
    }
