    return true;
  }

  int rows = precinctVotes.length, cols = precinctVotes[0].length;
  List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (precinctVotes[i][j] < threshold[0] || precinctVotes[i][j] > threshold[1]) {
        continue;
      }

      bool isolated = true;
      List<int> neighbors = [precinctVotes[i][j]];
      for (List<int> d in dirs) {
        int ni = i + d[0], nj = j + d[1];
        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && precinctVotes[ni][nj] >= threshold[0]) {
          neighbors.add(precinctVotes[ni][nj]);
          isolated = false;
        }
      }
      if (isolated) {
        return false;
      }
    }
  }

  for (int i = 0; i < rows; i++) {
    if (precinctVotes[i].length != cols) {
      return false;
    }
  }

  int totalSum = 0;
  for (int i = 0; i < rows * cols; i++) {
    totalSum += precinctVotes[i ~/ cols][i % cols];
  }
  if (totalSum < threshold[0] || totalSum > threshold[1]) {
    return false;
  }

  List<List<int>> flattened = [];
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      int idx = i * cols + j;
      if (idx >= 0 && idx < flattened.length) {
        flattened[idx] = [flattened[idx][0] + precinctVotes[i][j]];
      } else {
        flattened.add([precinctVotes[i][j]]);
      }
    }
  }

  for (int i = 0; i < flattened.length; i++) {
    if (flattened[i][0] < threshold[0] || flattened[i][0] > threshold[1]) {
      return false;
    }
  }

  return true;
}

