    return [-1, -1];
  }

  List<int> xs = [];
  List<int> ys = [];
  for (var pos in packetPositions) {
    xs.add(pos[0]);
    ys.add(pos[1]);
  }

  int minX = xs[0];
  int maxX = xs[0];
  int minY = ys[0];
  int maxY = ys[0];
  for (int i = 1; i < xs.length; i++) {
    if (xs[i] < minX) minX = xs[i];
    if (xs[i] > maxX) maxX = xs[i];
    if (ys[i] < minY) minY = ys[i];
    if (ys[i] > maxY) maxY = ys[i];
  }

  int overlapArea = 0;

  for (int x = minX; x <= maxX; x++) {
    for (int y = minY; y <= maxY; y++) {
      bool touching = false;
      for (var pos in packetPositions) {
        if (x == pos[0] && y == pos[1]) {
          touching = true;
          break;
        }
      }
      if (touching) {
        overlapArea += 1;
      }
    }
  }

  List<int> counts = List.filled(overlapArea + 1, 0);

  for (var pos in packetPositions) {
    int x = pos[0];
    int y = pos[1];
    int cx = (x - minX) % overlapArea;
    int cy = (y - minY) % overlapArea;
    counts[cx]++;
    counts[cy]++;
  }

  int bestCx = 0;
  int bestCy = 0;
  int bestCount = 0;
  for (int c = 0; c <= overlapArea; c++) {
    if (counts[c] > bestCount || (counts[c] == bestCount && c < bestCount)) {
      bestCount = counts[c];
      bestCx = c;
      bestCy = c;
    }
  }

