      List<int> right = [];
      int lo = 0;
      int hi = i - 1;
      while (lo <= hi) {
        int mid = (lo + hi) ~/ 2;
        if (quantities[mid] < threshold) {
          left.add(mid);
          lo = mid + 1;
        } else {
          hi = mid - 1;
        }
      }
      List<int> rightFromEnd = [];
      lo = i - 1;
      hi = 0;
      while (lo >= hi) {
        int mid = (lo + hi) ~/ 2;
        if (quantities[mid] < threshold) {
          rightFromEnd.add(mid);
          hi = mid - 1;
        } else {
          lo = mid;
        }
      }
      List<int> rightEnd = rightFromEnd.reversed.toList();
      clusters.add([...left, i, ...rightEnd]);
    }
  }
  List<int> result = [];
  for (List<int> cluster in clusters) {
    int lo = cluster[0];
    int hi = cluster[1];
    int mid = (lo + hi) ~/ 2;
    if (quantities[mid] > threshold) {
      result.add(mid);
    }
  }
