      } else {
        int best = -1;
        int bestIdx = -1;
        for (int k = 0; k < cols; k++) {
          int val = tallies[i][k];
          if (val > 0 && k != j) {
            int diff = (val - tallies[i][j]).abs();
            if (diff <= maxAbsDiff) {
              dp[i][j] = val;
              best = val;
              bestIdx = k;
            }
          }
        }
        dp[i][j] = best;
      }
    }
  }

  int winner = dp[rows - 1][cols - 1];
  if (winner == 0) return true;
  return (winner.abs() <= maxAbsDiff);
}

