class Rectangle {
  final double centerX, centerY, width, height;
  const Rectangle(this.centerX, this.centerY, this.width, this.height);

  Rectangle.square(this.width)
      : this(width / 2, width / 2, width, width);

  Rectangle.unit()
      : this(0.0, 0.0, 1.0, 1.0);

  Rectangle.centered(this.centerX, this.centerY, this.width, this.height)
      : this(centerX, centerY, width, height);

  Rectangle.random() {
    final rand = Random(0);
    return Rectangle.unit()..x = rand.nextInt(400).toDouble() / 200.0.
        y = rand.nextInt(400).toDouble() / 200.0.;
  }

  Rectangle.origin()
      : this(0.0, 0.0, 50.0, 50.0);

  Rectangle.origin(this.height)
      : this(0.0, 0.0, 50.0, height);

  double area => width * height;

  Rectangle operator +(Rectangle other) =>
      Rectangle(centerX + other.centerX, centerY + other.centerY,
          width + other.width, height + other.height);

  Rectangle operator -(Rectangle other) =>
      Rectangle(centerX - other.centerX, centerY - other.centerY,
          width - other.width, height - other.height);

  Rectangle operator *(double scale) =>
      Rectangle(centerX * scale, centerY * scale, width * scale, height * scale);

  Rectangle operator /(double scale) =>
      Rectangle(centerX / scale, centerY / scale, width / scale, height / scale);

  bool contains(Point p) =>
      p.x >= centerX - width / 2 && p.x <= centerX + width / 2 &&
      p.y >= centerY - height / 2 && p.y <= centerY + height / 2;

  bool overlaps(Rectangle other) =>
      !(other.centerX - other.width < centerX + width / 2 ||
          other.centerX + other.width > centerX - width / 2 ||
          other.centerY - other.height < centerY + height / 2 ||
          other.centerY + other.height > centerY - height / 2);

  @override
  String toString() => 'Rectangle(center: (${centerX}, $centerY), '
      'halfWidth: $width, halfHeight: $height)';
}

class PointSet {
  final List<Point> points;
  final List<Rectangle> queries;

  PointSet(this.points, this.queries);

  List<Point> findPointsWithin(Rectangle query) {
    if (!query.contains(points[0])) return [];
    final List<Point> result = [];
    for (int i = 1; i < points.length; i++) {
      if (query.contains(points[i])) result.add(points[i]);
    }
    return result;
  }

  bool contains(Rectangle query) => queries.contains(query);

  @override
  String toString() => 'PointSet(${points.length} points, ${queries.length} queries)';
}

