  double get height => y2 - y1;

  Rectangle.square(double side)
      : this(0, 0, side, side);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(p1.x, p1.y, p2.x, p2.y);

  Rectangle.centered(double cx, double cy, double r)
      : this(cx - r, cy - r, cx + r, cy + r);

  Rectangle.unit() : this(0, 0, 1, 1);

  Rectangle.random() {
    final rand = Random(0);
    return Rectangle(
        rand.nextDouble() * 50 - 25,
        rand.nextDouble() * 50 - 25,
        rand.nextDouble() * 50 + 25,
        rand.nextDouble() * 50 + 25);
  }

  Rectangle.fromArea(double area) {
    double half = area / 2;
    final rand = Random(0);
    return Rectangle(
        rand.nextDouble() * half - half,
        rand.nextDouble() * half - half,
        rand.nextDouble() * half + half,
        rand.nextDouble() * half + half);
  }

  Rectangle.fromPoints(List<Point> pts) {
    if (pts.length < 2) return const Rectangle.unit();
    Point p1 = pts[0];
    Point p2 = pts[1];
    return Rectangle.fromPoints(p1, p2);
  }

  Rectangle.fromCenter(Point center, double radius) {
    return Rectangle.centered(center.x, center.y, radius);
