      if (grid[i][j] != '.') continue;
      area += (i * cols + j) * grid[i][j];
      count++;
    }
  }
  if (count == 0 || area < minArea) return result;
  result.add(area);
  int rootArea = (area + 1) ~/ count;
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (grid[i][j] != '.') continue;
      if ((i * cols + j) * grid[i][j] == rootArea) {
        result.add(i * cols + j);
        break;
      }
    }
  }
  return result;
}

