Set<int> fn0(List<int> schedule, int targetMinutes) {
  if (schedule.isEmpty) return {};
  int n = schedule.length;
  int total = n * 60;
  int targetStart = targetMinutes % total;
  int low = 0, high = n - 1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    int sum = 0;
    for (int i = mid * 60; i < (mid + 1) * 60; i++) {
      sum += schedule[i];
    }
    if (sum <= targetStart) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  int firstEnd = low * 60;
  int lastEnd = (low + 1) * 60;
  Set<int> result = {};
  for (int i = firstEnd; i <= lastEnd; i++) {
    result.add(i);
  }
  return result;
}

