Set<int> fn0(List<int> readings) {
  if (readings.isEmpty) return {};
  int minVal = readings[0];
  int maxVal = readings[0];
  for (int r in readings) {
    if (r < minVal) minVal = r;
    if (r > maxVal) maxVal = r;
  }
  int total = 0;
  for (int v in readings) {
    total += v;
  }
  int avg = total / readings.length;
  Set<int> result = {};
  for (int i = 0; i < readings.length; i++) {
    if (readings[i] == avg) result.add(i);
  }
  int lo = minVal * readings.length;
  int hi = (maxVal * readings.length) + 1;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    int count = 0;
    for (int v in readings) {
      if (v <= mid) count++;
    }
    if (count >= readings.length) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  int threshold = lo < avg ? lo : avg;
  for (int r in readings) {
    if (r > threshold) result.add(r);
  }
  return result;
}

