          (j > 0 && grid[i][j] > grid[i][j - 1]);
      bool hasAdjacentPeak = (i > 0 && j > 0 && grid[i - 1][j - 1] == 1) ||
          (i > 0 && j < grid[i - 1].length - 1 && grid[i - 1][j + 1] == 1) ||
          (j > 0 && i < grid[j - 1].length - 1 && grid[j - 1][i + 1] == 1);
      if (!isPeak || !hasAdjacentPeak) continue;
      return true;
    }
  }
  return false;
}

